const listLedgerEntries = `-- name: ListLedgerEntries :many
SELECT id, organization_id, billing_period_id, billing_period_starts_at_snapshot, billing_period_ends_at_snapshot, entry_type, amount_micros, balance_after_micros, reservation_id, usage_record_id, team_id_snapshot, team_name_snapshot, source_reference, actor_reference, created_at, retain_until
FROM ledger_entries
WHERE organization_id = $1
  AND ($2::text = '' OR entry_type = $2)
  AND created_at >= $3
  AND created_at < $4
  AND id > $5
ORDER BY id
LIMIT $6
`

type ListLedgerEntriesParams struct {
	OrganizationID pgtype.UUID
	EntryType      string
	FromTime       pgtype.Timestamptz
	ToTime         pgtype.Timestamptz
	AfterID        pgtype.UUID
	PageLimit      int32
}

func (q *Queries) ListLedgerEntries(ctx context.Context, arg ListLedgerEntriesParams) ([]LedgerEntry, error) {
	rows, err := q.db.Query(ctx, listLedgerEntries,
		arg.OrganizationID,
		arg.EntryType,
		arg.FromTime,
		arg.ToTime,
		arg.AfterID,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LedgerEntry{}
	for rows.Next() {
		var i LedgerEntry
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.BillingPeriodID,
			&i.BillingPeriodStartsAtSnapshot,
			&i.BillingPeriodEndsAtSnapshot,
			&i.EntryType,
			&i.AmountMicros,
			&i.BalanceAfterMicros,
			&i.ReservationID,
			&i.UsageRecordID,
			&i.TeamIDSnapshot,
			&i.TeamNameSnapshot,
			&i.SourceReference,
			&i.ActorReference,
			&i.CreatedAt,
			&i.RetainUntil,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

