const reconcileInactiveBillingPeriodForReplacement = `-- name: ReconcileInactiveBillingPeriodForReplacement :execrows
UPDATE billing_periods AS period
SET subscription_id = CASE
        WHEN period.starts_at = $1
            THEN $2
        ELSE period.subscription_id
    END,
    ends_at = CASE
        WHEN period.starts_at = $1
            THEN $3
        ELSE $1
    END
FROM subscriptions AS subscription
WHERE period.organization_id = $4
  AND period.subscription_id = subscription.id
  AND subscription.organization_id = period.organization_id
  AND period.subscription_id <> $2
  AND subscription.status IN ('past_due', 'canceled', 'revoked')
  AND period.starts_at <= $1
  AND period.ends_at > $1
`

type ReconcileInactiveBillingPeriodForReplacementParams struct {
	ReplacementStartsAt       pgtype.Timestamptz
	ReplacementSubscriptionID pgtype.UUID
	ReplacementEndsAt         pgtype.Timestamptz
	OrganizationID            pgtype.UUID
}

func (q *Queries) ReconcileInactiveBillingPeriodForReplacement(ctx context.Context, arg ReconcileInactiveBillingPeriodForReplacementParams) (int64, error) {
	result, err := q.db.Exec(ctx, reconcileInactiveBillingPeriodForReplacement,
		arg.ReplacementStartsAt,
		arg.ReplacementSubscriptionID,
		arg.ReplacementEndsAt,
		arg.OrganizationID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateCurrentBillingPeriodOverageLimit = `-- name: UpdateCurrentBillingPeriodOverageLimit :execrows
WITH current_period AS (
    SELECT id, starts_at, ends_at
    FROM billing_periods AS candidate
    WHERE candidate.organization_id = $2
      AND candidate.starts_at <= transaction_timestamp()
      AND candidate.ends_at > transaction_timestamp()
    FOR UPDATE
), committed AS (
    SELECT COALESCE(sum(overage_applied_micros), 0)::bigint AS amount
    FROM usage_records AS record
    JOIN current_period
      ON record.committed_at >= current_period.starts_at
     AND record.committed_at < current_period.ends_at
    WHERE record.organization_id = $2
), held AS (
    SELECT COALESCE(sum(held_overage_micros), 0)::bigint AS amount
    FROM usage_reservations AS reservation
    JOIN current_period
      ON reservation.created_at >= current_period.starts_at
     AND reservation.created_at < current_period.ends_at
    WHERE reservation.organization_id = $2
      AND reservation.status = 'held'
), shortfall AS (
    SELECT COALESCE(sum(amount_micros), 0)::bigint AS amount
    FROM billing_shortfalls AS item
    JOIN current_period ON item.billing_period_id = current_period.id
    WHERE item.organization_id = $2
)
UPDATE billing_periods AS period
SET requested_overage_limit_micros = $1,
    overage_limit_micros = GREATEST(
        $1,
        (SELECT amount FROM committed)
            + (SELECT amount FROM held)
            + (SELECT amount FROM shortfall)
    )
FROM current_period
WHERE period.id = current_period.id
`

type UpdateCurrentBillingPeriodOverageLimitParams struct {
	OverageLimitMicros int64
	OrganizationID     pgtype.UUID
}

func (q *Queries) UpdateCurrentBillingPeriodOverageLimit(ctx context.Context, arg UpdateCurrentBillingPeriodOverageLimitParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateCurrentBillingPeriodOverageLimit, arg.OverageLimitMicros, arg.OrganizationID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

